page_auth_v172:
"""光鸭转存助手页面 API 与页面故障隔离兼容层。

MoviePilot V3 插件页面使用当前登录会话的 Bearer 鉴权。页面事件只传业务参数，
不把 API_TOKEN 作为 token/apikey 注入按钮参数。

状态页的“立即检查缺集/复查待落盘”不能在 HTTP 请求线程里同步跑完整频道读取、
分享解析和转存流程，否则前端会在网络稍慢时提示“服务无响应”。本层把这两类操作
送入插件已经存在的可靠后台合并队列，并立即返回标准三段式 Response envelope；
其余状态页操作也统一收口为严格的 success/message/data 三字段响应。

v1.10.2 追加页面故障隔离：新版控制台会同时读取自检、资源计划、频道缓存、Provider
配置和迅雷运行态。升级后任意一份旧缓存形态异常，或者任意运行时探针抛错，都不应让
MoviePilot 整个插件页返回“数据加载失败”。本层在不改变转存业务逻辑的前提下，对这些
只读页面数据做 fail-soft 包装：失败模块降级显示，控制台本身继续可用，并把详细异常写入
插件日志供排障。
"""

from __future__ import annotations

import functools
from typing import Any, Dict, List


_STATUS_ACTION_PATHS = {
    "/check_missing",
    "/recheck_pending",
    "/cancel_pending",
    "/reset_state",
    "/release_native",
    "/daily_summary",
    "/clear_plugin_logs",
}
_ASYNC_STATUS_PATHS = {
    "/check_missing": "状态页立即检查缺集",
    "/recheck_pending": "状态页复查待落盘",
}


def _response_envelope(result: Any, default_message: str = "操作完成") -> Dict[str, Any]:
    """把旧版插件 API 返回值规范成 MoviePilot V3 严格三段式响应。"""
    if isinstance(result, dict):
        success = bool(result.get("success", True))
        message = str(result.get("message") or (default_message if success else "操作失败"))
        data = {
            key: value
            for key, value in result.items()
            if key not in {"success", "message"}
        }
        return {
            "success": success,
            "message": message,
            "data": data or None,
        }
    return {
        "success": True,
        "message": default_message,
        "data": result,
    }


def _subscription_id(args: tuple, kwargs: dict) -> int:
    """从 FastAPI 绑定参数中稳健取得 subscribe_id。"""
    value = kwargs.get("subscribe_id")
    if value in (None, "") and args:
        value = args[0]
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _queue_status_action(path: str, endpoint: Any, *args, **kwargs) -> Dict[str, Any]:
    """校验状态页耗时操作并提交现有可靠后台队列，HTTP 立即返回。"""
    plugin = getattr(endpoint, "__self__", None)
    if plugin is None:
        return {
            "success": False,
            "message": "插件运行实例不可用，请刷新页面后重试",
            "data": None,
        }

    sid = _subscription_id(args, kwargs)
    subscribe = plugin._find_subscription(sid) if sid else None
    if not sid or subscribe is None:
        return {
            "success": False,
            "message": "订阅不存在",
            "data": {"subscribe_id": sid} if sid else None,
        }

    selected = {
        int(value)
        for value in (getattr(plugin, "_selected_subscriptions", None) or [])
        if str(value).isdigit() and int(value) > 0
    }
    if sid not in selected:
        return {
            "success": False,
            "message": "该订阅当前不是光鸭固定转存路线",
            "data": {"subscribe_id": sid},
        }

    runtime_check = getattr(plugin, "_runtime_is_current", None)
    if callable(runtime_check) and not runtime_check():
        return {
            "success": False,
            "message": "插件已热更新，请刷新当前页面后重试",
            "data": {"subscribe_id": sid},
        }

    # “立即检查缺集”保留原人工门禁：已有待落盘任务时不能强制重放旧消息。
    if path == "/check_missing":
        manual_guard = getattr(plugin, "_manual_transfer_guard", None)
        if callable(manual_guard):
            guard = manual_guard(subscribe)
            if guard:
                return _response_envelope(guard, default_message="检查被安全门禁阻止")

    trigger = _ASYNC_STATUS_PATHS[path]
    try:
        plugin._queue_async_route_check([sid], trigger=trigger)
        record_health = getattr(plugin, "_record_route_health", None)
        if callable(record_health):
            record_health(
                last_page_action_queued=trigger,
                last_page_action_id=sid,
                last_page_action_at=plugin._now_text(),
            )
        plugin._plugin_log(
            "INFO",
            "【光鸭转存助手】【页面操作】%s #%s %s 已进入后台队列，HTTP 请求立即返回",
            trigger,
            sid,
            getattr(subscribe, "name", ""),
        )
    except Exception as err:
        plugin._plugin_log(
            "EXCEPTION",
            "【光鸭转存助手】【页面操作】%s #%s 入队失败：%s",
            trigger,
            sid,
            err,
        )
        return {
            "success": False,
            "message": f"后台任务提交失败：{err}",
            "data": {"subscribe_id": sid},
        }

    return {
        "success": True,
        "message": "已进入后台检查队列，请稍后查看状态卡片或插件日志",
        "data": {
            "subscribe_id": sid,
            "queued": True,
            "action": path.lstrip("/"),
        },
    }


def _wrap_status_endpoint(path: str, endpoint: Any) -> Any:
    """保持原 FastAPI 签名，同时统一状态页操作响应。"""
    if path in _ASYNC_STATUS_PATHS:
        @functools.wraps(endpoint)
        def queued_endpoint(*args, **kwargs):
            return _queue_status_action(path, endpoint, *args, **kwargs)

        return queued_endpoint

    @functools.wraps(endpoint)
    def response_endpoint(*args, **kwargs):
        return _response_envelope(endpoint(*args, **kwargs))

    return response_endpoint


def force_bear_auth(routes: Any) -> List[Dict[str, Any]]:
    """统一 Bearer 鉴权，并给状态页按钮安装非阻塞/标准响应适配器。"""
    result: List[Dict[str, Any]] = []
    for route in list(routes or []):
        if not isinstance(route, dict):
            continue
        item = dict(route)
        item["auth"] = "bear"
        path = str(item.get("path") or "")
        endpoint = item.get("endpoint")
        if path in _STATUS_ACTION_PATHS and callable(endpoint):
            item["endpoint"] = _wrap_status_endpoint(path, endpoint)
        result.append(item)
    return result


def strip_page_api_secrets(node: Any) -> None:
    """递归移除状态页按钮中的 token/apikey，仅保留业务参数。"""
    if isinstance(node, dict):
        events = node.get("events")
        if isinstance(events, dict):
            click = events.get("click")
            if isinstance(click, dict) and str(click.get("api") or "").startswith(
                "plugin/GuangYaTransferAssistant/"
            ):
                params = click.get("params")
                if isinstance(params, dict):
                    params.pop("token", None)
                    params.pop("apikey", None)
        for value in node.values():
            strip_page_api_secrets(value)
    elif isinstance(node, list):
        for value in node:
            strip_page_api_secrets(value)


# ---------------------------------------------------------------------------
# v1.10.2 页面数据故障隔离
# ---------------------------------------------------------------------------

def _page_log_error(plugin: Any, stage: str, err: Exception) -> None:
    """页面降级只记录异常，不让记录异常本身再次影响页面返回。"""
    try:
        log = getattr(plugin, "_plugin_log", None)
        if callable(log):
            log(
                "EXCEPTION",
                "【光鸭转存助手】【页面降级】%s 读取失败，已隔离该模块：%s",
                stage,
                err,
            )
    except Exception:
        pass


def _page_mark_error(plugin: Any, stage: str, err: Exception) -> None:
    """记录当前一次页面构建的降级模块名称，前端只展示模块名而不泄露异常原文。"""
    _page_log_error(plugin, stage, err)
    try:
        rows = getattr(plugin, "_page_resilience_errors_v1102", None)
        if not isinstance(rows, list):
            rows = []
            setattr(plugin, "_page_resilience_errors_v1102", rows)
        if stage not in rows:
            rows.append(stage)
    except Exception:
        pass


def _fallback_overview(plugin: Any, stage: str = "状态汇总") -> Dict[str, Any]:
    """提供新控制台所需的完整最小字段，避免二次 KeyError。"""
    try:
        selected = len(list(getattr(plugin, "_selected_subscriptions", None) or []))
    except Exception:
        selected = 0
    return {
        "overall": "warning",
        "healthy": False,
        "attention_count": 0,
        "selected": selected,
        "channel_count": 0,
        "channel_updated": "-",
        "channel_errors": 0,
        "sources": {
            "total": 0,
            "magnet": 0,
            "ed2k": 0,
            "pending": 0,
            "running": 0,
            "completed": 0,
            "failed": 0,
            "review": 0,
        },
        "critical_checks": [],
        "warning_checks": [{
            "key": "page_data_degraded",
            "label": "页面状态数据已降级",
            "detail": f"{stage}暂时不可用，后台转存任务不会因此停止",
            "critical": False,
            "ok": False,
        }],
        "attention_sources": [],
        "failed_transfer_rows": [],
        "active_sources": [],
        "active_transfer_rows": [],
        "waiting_resource_count": 0,
        "resource_plan_count": 0,
        "version": str(getattr(plugin, "plugin_version", "")),
        "build": str(getattr(plugin, "build_id", "")),
        "viewing": {
            "enabled": bool(getattr(plugin, "_viewing_enabled", False)),
            "active_node": "",
            "status": "unknown",
            "verified": False,
            "login_mode": "",
        },
        "xunlei_flash": {
            "enabled": bool(getattr(plugin, "_xunlei_flash_enabled", True)),
            "completed": 0,
            "failed": 0,
        },
        "page_degraded": True,
        "page_degraded_stage": stage,
    }


def _page_fallback_cards(plugin: Any, stage: str) -> List[Dict[str, Any]]:
    """即便主控制台构建异常，也返回 MoviePilot 能渲染的最小页面而不是 HTTP 失败。"""
    version = str(getattr(plugin, "plugin_version", "") or "-")
    build = str(getattr(plugin, "build_id", "") or "-")
    return [
        {
            "component": "VAlert",
            "props": {
                "type": "warning",
                "variant": "tonal",
                "title": "控制台已降级显示",
                "text": (
                    f"{stage}读取异常，已隔离故障模块。后台转存逻辑不会因页面异常被停止。"
                    "请先打开插件设置检查配置，或查看后台日志中的【页面降级】记录。"
                ),
                "class": "mb-3",
                "style": "border-radius:16px;",
            },
        },
        {
            "component": "VCard",
            "props": {"variant": "flat", "class": "mb-3"},
            "content": [
                {"component": "VCardTitle", "text": "光鸭转存助手"},
                {
                    "component": "VCardText",
                    "text": f"v{version} · build {build} · 页面保护模式已生效",
                },
            ],
        },
    ]


def _install_page_resilience_v1102() -> None:
    """给已加载的 UI mixin 安装 fail-soft 包装；重复导入时保持幂等。"""
    try:
        from .status_ui_v191 import GuangYaStatusUiMixin
        from .console_ui_v1100 import GuangYaConsoleUiV1100Mixin
        from .channel_ui_v1101 import GuangYaChannelUiV1101Mixin
    except Exception:
        # 极早期兼容环境缺少某个新版 UI 模块时，不影响插件原有导入路径。
        return

    # 1) 状态汇总是新版控制台的总入口。旧缓存/ResourcePlan/自检任一异常都只返回降级数据。
    original_overview = getattr(GuangYaStatusUiMixin, "_status_overview_v191", None)
    if callable(original_overview) and not getattr(original_overview, "_guangya_page_resilience_v1102", False):
        @functools.wraps(original_overview)
        def safe_overview(self, *args, **kwargs):
            try:
                result = original_overview(self, *args, **kwargs)
                if not isinstance(result, dict):
                    raise TypeError("status overview is not a dict")
                return result
            except Exception as err:
                _page_mark_error(self, "状态汇总", err)
                return _fallback_overview(self, "状态汇总")

        safe_overview._guangya_page_resilience_v1102 = True
        GuangYaStatusUiMixin._status_overview_v191 = safe_overview

    # 2) Provider 定义解析此前没有 try/except，单行历史配置格式错误即可拖死整页。
    original_health = getattr(GuangYaConsoleUiV1100Mixin, "_runtime_health_rows", None)
    if callable(original_health) and not getattr(original_health, "_guangya_page_resilience_v1102", False):
        @functools.wraps(original_health)
        def safe_health(self, *args, **kwargs):
            try:
                result = original_health(self, *args, **kwargs)
                return list(result or [])
            except Exception as err:
                _page_mark_error(self, "资源来源运行态", err)
                return [{
                    "component": "VCol",
                    "props": {"cols": 12},
                    "content": [{
                        "component": "VAlert",
                        "props": {
                            "type": "warning",
                            "variant": "tonal",
                            "density": "compact",
                            "text": "资源来源运行态暂时无法读取，已跳过该模块；可继续使用其它控制台功能。",
                            "style": "border-radius:14px;",
                        },
                    }],
                }]

        safe_health._guangya_page_resilience_v1102 = True
        GuangYaConsoleUiV1100Mixin._runtime_health_rows = safe_health

    # 3) 频道索引是 v1.10.1 新增区块；坏的 channel_index 不应反向拖垮 v1.10.0 主控制台。
    original_channel_card = getattr(GuangYaChannelUiV1101Mixin, "_channel_page_card_v1101", None)
    if callable(original_channel_card) and not getattr(original_channel_card, "_guangya_page_resilience_v1102", False):
        @functools.wraps(original_channel_card)
        def safe_channel_card(self, *args, **kwargs):
            try:
                result = original_channel_card(self, *args, **kwargs)
                if not isinstance(result, dict):
                    raise TypeError("channel card is not a dict")
                return result
            except Exception as err:
                _page_mark_error(self, "频道资源", err)
                return {
                    "component": "VAlert",
                    "props": {
                        "type": "warning",
                        "variant": "tonal",
                        "density": "compact",
                        "class": "mb-4",
                        "title": "频道资源暂时无法读取",
                        "text": "频道索引异常已被隔离，不影响其它状态卡和后台转存。可尝试重新刷新频道。",
                        "style": "border-radius:14px;",
                    },
                }

        safe_channel_card._guangya_page_resilience_v1102 = True
        GuangYaChannelUiV1101Mixin._channel_page_card_v1101 = safe_channel_card

    # 4) 最外层兜底。任何未来新增页面模块忘记做容错，也不能再向 MoviePilot 抛出整页异常。
    original_console_page = getattr(GuangYaConsoleUiV1100Mixin, "get_page", None)
    if callable(original_console_page) and not getattr(original_console_page, "_guangya_page_resilience_v1102", False):
        @functools.wraps(original_console_page)
        def safe_console_page(self, *args, **kwargs):
            try:
                result = original_console_page(self, *args, **kwargs)
                if not isinstance(result, list):
                    raise TypeError("console page is not a list")
                return result
            except Exception as err:
                _page_mark_error(self, "主控制台", err)
                return _page_fallback_cards(self, "主控制台")

        safe_console_page._guangya_page_resilience_v1102 = True
        GuangYaConsoleUiV1100Mixin.get_page = safe_console_page

    # 5) ChannelUi 位于最终 MRO 最前；再兜一层可覆盖频道 get_page 自身的插入逻辑异常。
    original_channel_page = getattr(GuangYaChannelUiV1101Mixin, "get_page", None)
    if callable(original_channel_page) and not getattr(original_channel_page, "_guangya_page_resilience_v1102", False):
        @functools.wraps(original_channel_page)
        def safe_channel_page(self, *args, **kwargs):
            try:
                setattr(self, "_page_resilience_errors_v1102", [])
            except Exception:
                pass
            try:
                result = original_channel_page(self, *args, **kwargs)
                if not isinstance(result, list):
                    raise TypeError("plugin page is not a list")
            except Exception as err:
                _page_mark_error(self, "页面总入口", err)
                return _page_fallback_cards(self, "页面总入口")

            try:
                errors = list(getattr(self, "_page_resilience_errors_v1102", None) or [])
            except Exception:
                errors = []
            if errors:
                result.insert(0, {
                    "component": "VAlert",
                    "props": {
                        "type": "warning",
                        "variant": "tonal",
                        "density": "compact",
                        "class": "mb-4",
                        "title": "部分状态数据已降级",
                        "text": "已隔离：" + "、".join(errors[:6]) + "。页面其余功能可继续使用，详细原因见后台【页面降级】日志。",
                        "style": "border-radius:14px;",
                    },
                })
            return result

        safe_channel_page._guangya_page_resilience_v1102 = True
        GuangYaChannelUiV1101Mixin.get_page = safe_channel_page


_install_page_resilience_v1102()


__all__ = [
    "force_bear_auth",
    "strip_page_api_secrets",
]

pow_singleflight_v209:
"""2.0.9-r93：同一 GYING 节点 PanSou PoW singleflight。

禁止并发订阅各自重复求解同一节点 challenge；等待首个求解结果并复用会话。
不改写 gying_browser / gying_pow / gying_pansou 核心算法，只在求解入口加锁合并。
"""
from __future__ import annotations

import threading
import time
from typing import Any, Dict, Optional

from .gying_hardening_v193 import canonical_gying_node


class GuangYaPowSingleflightV209Mixin:
    """Per-node PoW singleflight around `_gying_solve_challenge_v1110`."""

    _pow_singleflight_master_v209 = threading.RLock()
    _pow_singleflight_overflow_v209 = threading.RLock()

    def init_plugin(self, config: dict = None) -> None:
        self._pow_singleflight_locks_v209: Dict[str, threading.RLock] = {}
        self._pow_singleflight_results_v209: Dict[str, Dict[str, Any]] = {}
        return super().init_plugin(config)

    def _pow_node_key_v209(self, node: str) -> str:
        return canonical_gying_node(node) or str(node or "").rstrip("/").lower()

    def _pow_lock_for_node_v209(self, node_key: str) -> threading.RLock:
        master = getattr(self, "_pow_singleflight_master_v209", None) or threading.RLock()
        self._pow_singleflight_master_v209 = master
        with master:
            locks = getattr(self, "_pow_singleflight_locks_v209", None)
            if not isinstance(locks, dict):
                locks = {}
                self._pow_singleflight_locks_v209 = locks
            lock = locks.get(node_key)
            if lock is not None:
                return lock
            if len(locks) >= 64:
                return getattr(self, "_pow_singleflight_overflow_v209", None) or threading.RLock()
            lock = threading.RLock()
            locks[node_key] = lock
            return lock

    def _gying_solve_challenge_v1110(
        self,
        session,
        node: str,
        response,
        kind: Optional[str] = None,
    ) -> Dict[str, Any]:
        node_key = self._pow_node_key_v209(node)
        kind_token = str(kind or "")
        # Only coalesce remote_pow / empty kind (resolved inside); still serialize all solves per node.
        lock = self._pow_lock_for_node_v209(node_key or "-")
        with lock:
            cache = getattr(self, "_pow_singleflight_results_v209", None)
            if not isinstance(cache, dict):
                cache = {}
                self._pow_singleflight_results_v209 = cache
            cached = dict(cache.get(node_key) or {})
            try:
                age = time.monotonic() - float(cached.get("at") or 0)
            except (TypeError, ValueError):
                age = 10**9
            # Fresh verified solve within 45s can be reused by waiters on the same node.
            if cached.get("ok") and age < 45:
                bump = getattr(self, "_bump_metric_v209", None)
                if callable(bump):
                    bump("cache_hits")
                return dict(cached.get("result") or {"success": True, "reused": True, "node": node_key})

            bump = getattr(self, "_bump_metric_v209", None)
            if callable(bump):
                bump("pansou_pow_challenges")
            result = dict(
                super()._gying_solve_challenge_v1110(session, node, response, kind=kind_token or kind) or {}
            )
            cache[node_key] = {
                "at": time.monotonic(),
                "ok": True,
                "result": dict(result),
            }
            return result


__all__ = ["GuangYaPowSingleflightV209Mixin"]

production_safety_v208:
"""2.0.8-r92 production safety：外部补搜入队、识别短缓存、失效 tombstone、失败通知汇总。

不重写身份门禁 / Episode Fence / 迅雷 / GYING；只补齐实机暴露的边界行为。
"""
from __future__ import annotations

import copy
import threading
import time
from typing import Any, Dict, Iterable, List, Optional

from app.chain.media import MediaChain

from .media_source_v209 import is_tmdb_source, normalize_media_source_token
from .transfer_diag_v209 import (
    batch_summary_buckets,
    classify_transfer_message_v209,
    format_batch_summary,
)


class GuangYaProductionSafetyV208Mixin:
    """薄安全层：异步 GYING 补搜、同轮识别缓存、分享 tombstone、批次失败通知。"""

    _recognize_cache_ttl_v208 = 90
    _recognize_miss_ttl_v208 = 15
    _external_recall_dedup_seconds_v208 = 180
    _tombstone_expired_ttl_v208 = 12 * 3600
    _tombstone_temp_ttl_v208 = 10 * 60

    def init_plugin(self, config: dict = None) -> None:
        self._recognize_cache_lock_v208 = threading.RLock()
        self._recognize_cache_v208: Dict[str, Dict[str, Any]] = {}
        self._external_recall_lock_v208 = threading.RLock()
        self._external_recall_pending_v208: Dict[str, float] = {}
        self._tombstone_lock_v208 = threading.RLock()
        self._share_tombstone_v208: Dict[str, Dict[str, Any]] = {}
        self._failure_batch_lock_v208 = threading.RLock()
        self._failure_batch_v208: List[Dict[str, Any]] = []
        self._failure_batch_active_v208 = 0
        return super().init_plugin(config)

    @staticmethod
    def _enum_token_v208(value: Any) -> str:
        return str(getattr(value, "value", value) or "").strip().lower()

    @classmethod
    def _normalize_mtype_v208(cls, value: Any) -> str:
        text = cls._enum_token_v208(value)
        if "movie" in text or "电影" in text:
            return "movie"
        if "tv" in text or "剧" in text or "anime" in text or "动漫" in text:
            return "tv"
        return text or "-"

    @classmethod
    def _recognize_cache_key_v208(cls, **kwargs: Any) -> str:
        meta = kwargs.get("meta")
        media_id = str(kwargs.get("media_id") or "").strip()
        if not media_id and meta is not None:
            media_id = str(getattr(meta, "tmdb_id", None) or getattr(meta, "media_id", None) or "").strip()
        media_source = normalize_media_source_token(kwargs.get("media_source"))
        if not media_source and meta is not None:
            media_source = normalize_media_source_token(getattr(meta, "media_source", None))
        mtype = cls._normalize_mtype_v208(kwargs.get("mtype"))
        if mtype in {"", "-"} and meta is not None:
            mtype = cls._normalize_mtype_v208(getattr(meta, "type", None))
        title = str(kwargs.get("title") or kwargs.get("name") or "").strip().casefold()
        if not title and meta is not None:
            title = str(getattr(meta, "title", None) or getattr(meta, "name", None) or getattr(meta, "cn_name", None) or "").strip().casefold()
        year = str(kwargs.get("year") or "").strip()
        if not year and meta is not None:
            year = str(getattr(meta, "year", None) or "").strip()
        season = kwargs.get("season")
        if season in (None, "") and meta is not None:
            season = getattr(meta, "begin_season", None)
            if season in (None, ""):
                season = getattr(meta, "season", None)
        try:
            season_token = str(int(season)) if season not in (None, "") else "-"
        except (TypeError, ValueError):
            season_token = "-"

        if media_id:
            source_token = media_source or ("tmdb" if media_id.isdigit() else "id")
            if media_id.isdigit() and (not media_source or media_source == "tmdb"):
                source_token = "tmdb"
            # 有确定 ID 时按 identity 去重；不同季共享同一 MediaInfo identity。
            return f"id:{source_token}:{mtype}:{media_id}"
        if title:
            return f"title:{mtype}:{title}:{year}:s{season_token}"
        return ""

    @staticmethod
    def _clone_recognize_value_v208(value: Any) -> Any:
        if value is None or isinstance(value, (str, int, float, bool)):
            return value
        try:
            return copy.copy(value)
        except Exception:
            return value

    def _recognize_media_cached_v208(self, **kwargs: Any) -> Any:
        key = self._recognize_cache_key_v208(**kwargs)
        if not key:
            return MediaChain().recognize_media(**kwargs)

        now = time.time()
        lock = getattr(self, "_recognize_cache_lock_v208", None) or threading.RLock()
        self._recognize_cache_lock_v208 = lock
        cache = getattr(self, "_recognize_cache_v208", None)
        if not isinstance(cache, dict):
            cache = {}
            self._recognize_cache_v208 = cache
        with lock:
            row = dict(cache.get(key) or {})
            try:
                age = now - float(row.get("at") or 0)
            except (TypeError, ValueError):
                age = 10**9
            ttl = float(self._recognize_cache_ttl_v208 if row.get("value") is not None else self._recognize_miss_ttl_v208)
            if row and age < ttl and "value" in row:
                self._plugin_log("INFO", "【光鸭转存助手】【媒体识别】key=%s cache=hit", key[:120])
                return self._clone_recognize_value_v208(row.get("value"))

        try:
            value = MediaChain().recognize_media(**kwargs)
        except Exception:
            # timeout / DNS / 5xx 等临时失败不写负缓存。
            raise
        with lock:
            cache[key] = {"at": now, "value": value}
            if len(cache) > 256:
                ordered = sorted(cache.items(), key=lambda pair: float((pair[1] or {}).get("at") or 0), reverse=True)[:256]
                self._recognize_cache_v208 = dict(ordered)
        return self._clone_recognize_value_v208(value)

    def _recognize_by_meta_cached_v208(self, meta: Any, **kwargs: Any) -> Any:
        payload = dict(kwargs)
        payload["meta"] = meta
        if "mtype" not in payload and meta is not None:
            payload["mtype"] = getattr(meta, "type", None)
        if "title" not in payload and meta is not None:
            payload["title"] = getattr(meta, "title", None) or getattr(meta, "name", None)
        if "year" not in payload and meta is not None:
            payload["year"] = getattr(meta, "year", None)
        key = self._recognize_cache_key_v208(**payload)
        if not key:
            return MediaChain().recognize_by_meta(meta, **kwargs)
        key = f"meta:{key}"
        now = time.time()
        lock = getattr(self, "_recognize_cache_lock_v208", None) or threading.RLock()
        self._recognize_cache_lock_v208 = lock
        cache = getattr(self, "_recognize_cache_v208", None)
        if not isinstance(cache, dict):
            cache = {}
            self._recognize_cache_v208 = cache
        with lock:
            row = dict(cache.get(key) or {})
            try:
                age = now - float(row.get("at") or 0)
            except (TypeError, ValueError):
                age = 10**9
            ttl = float(self._recognize_cache_ttl_v208 if row.get("value") is not None else self._recognize_miss_ttl_v208)
            if row and age < ttl and "value" in row:
                self._plugin_log("INFO", "【光鸭转存助手】【媒体识别】key=%s cache=hit", key[:120])
                return self._clone_recognize_value_v208(row.get("value"))
        try:
            value = MediaChain().recognize_by_meta(meta, **kwargs)
        except Exception:
            raise
        with lock:
            cache[key] = {"at": now, "value": value}
            if len(cache) > 256:
                ordered = sorted(cache.items(), key=lambda pair: float((pair[1] or {}).get("at") or 0), reverse=True)[:256]
                self._recognize_cache_v208 = dict(ordered)
        return self._clone_recognize_value_v208(value)

    def _enqueue_external_recall_v208(self, subscribe: Any, reason: str = "local_candidates_exhausted") -> bool:
        try:
            sid = int(getattr(subscribe, "id", 0) or 0)
        except (TypeError, ValueError):
            sid = 0
        if sid <= 0:
            return False
        now = time.time()
        lock = getattr(self, "_external_recall_lock_v208", None) or threading.RLock()
        self._external_recall_lock_v208 = lock
        pending = getattr(self, "_external_recall_pending_v208", None)
        if not isinstance(pending, dict):
            pending = {}
            self._external_recall_pending_v208 = pending
        with lock:
            last = float(pending.get(str(sid)) or 0)
            if last and now - last < float(self._external_recall_dedup_seconds_v208):
                self._plugin_log(
                    "INFO",
                    "【光鸭转存助手】【外部补搜】sid=%s reason=%s decision=dedup",
                    sid,
                    str(reason or "")[:120],
                )
                return False
            pending[str(sid)] = now
            if len(pending) > 1000:
                self._external_recall_pending_v208 = dict(
                    sorted(pending.items(), key=lambda pair: float(pair[1] or 0), reverse=True)[:1000]
                )
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【外部补搜】sid=%s reason=%s decision=enqueue_gying",
            sid,
            str(reason or "")[:120],
        )
        self._queue_async_route_check([sid], trigger="外部补搜·本地候选耗尽")
        return True

    def _share_tombstone_key_v208(self, source_type: str, identity: str) -> str:
        return f"{str(source_type or 'guangya').strip().lower()}|{str(identity or '').strip()}"

    def _is_share_tombstoned_v208(self, source_type: str, identity: str) -> bool:
        key = self._share_tombstone_key_v208(source_type, identity)
        if not key.endswith("|") and key.split("|", 1)[-1]:
            pass
        else:
            return False
        now = time.time()
        lock = getattr(self, "_tombstone_lock_v208", None) or threading.RLock()
        self._tombstone_lock_v208 = lock
        store = getattr(self, "_share_tombstone_v208", None)
        if not isinstance(store, dict):
            store = {}
            self._share_tombstone_v208 = store
        with lock:
            row = dict(store.get(key) or {})
            try:
                until = float(row.get("until") or 0)
            except (TypeError, ValueError):
                until = 0
            if until > now:
                return True
            if key in store:
                store.pop(key, None)
        return False

    def _mark_share_tombstone_v208(self, source_type: str, identity: str, reason: str, *, temporary: bool = False) -> None:
        key = self._share_tombstone_key_v208(source_type, identity)
        if not str(identity or "").strip():
            return
        ttl = self._tombstone_temp_ttl_v208 if temporary else self._tombstone_expired_ttl_v208
        until = time.time() + float(ttl)
        lock = getattr(self, "_tombstone_lock_v208", None) or threading.RLock()
        self._tombstone_lock_v208 = lock
        store = getattr(self, "_share_tombstone_v208", None)
        if not isinstance(store, dict):
            store = {}
            self._share_tombstone_v208 = store
        with lock:
            store[key] = {"until": until, "reason": str(reason or "")[:240], "temporary": bool(temporary)}
            if len(store) > 2000:
                self._share_tombstone_v208 = dict(
                    sorted(store.items(), key=lambda pair: float((pair[1] or {}).get("until") or 0), reverse=True)[:2000]
                )
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【资源失效】share_id=%s reason=%s ttl=%s",
            str(identity or "")[:80],
            str(reason or "")[:160],
            int(ttl),
        )

    def _begin_failure_batch_v208(self) -> None:
        lock = getattr(self, "_failure_batch_lock_v208", None) or threading.RLock()
        self._failure_batch_lock_v208 = lock
        with lock:
            self._failure_batch_active_v208 = int(getattr(self, "_failure_batch_active_v208", 0) or 0) + 1
            if not isinstance(getattr(self, "_failure_batch_v208", None), list):
                self._failure_batch_v208 = []
            if not isinstance(getattr(self, "_diag_batch_v209", None), list):
                self._diag_batch_v209 = []
        try:
            instance = ""
            getter = getattr(self, "_instance_id_marker_v209", None)
            if callable(getter):
                instance = str(getter() or "")
            else:
                instance = str(getattr(self, "_instance_id_v209", "") or "")
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【批次开始】version=%s build=%s instance=%s",
                str(getattr(self, "plugin_version", "") or ""),
                str(getattr(self, "build_id", "") or ""),
                instance or "-",
            )
        except Exception:
            pass

    def _record_transfer_diag_v209(self, subscribe: Any, diag: Dict[str, Any], *, final: bool = True) -> None:
        """Accumulate structured diags for end-of-batch summary (upsert by subscription_run_id)."""
        lock = getattr(self, "_failure_batch_lock_v208", None) or threading.RLock()
        self._failure_batch_lock_v208 = lock
        with lock:
            if int(getattr(self, "_failure_batch_active_v208", 0) or 0) <= 0:
                return
            rows = getattr(self, "_diag_batch_v209", None)
            if not isinstance(rows, list):
                rows = []
                self._diag_batch_v209 = rows
            item = dict(diag or {})
            item.setdefault("sid", int(getattr(subscribe, "id", 0) or 0))
            item.setdefault("subscribe_title", str(getattr(subscribe, "name", "") or ""))
            item["_final"] = bool(final)
            run_id = str(item.get("subscription_run_id") or "").strip()
            if run_id:
                for idx, existing in enumerate(rows):
                    if str((existing or {}).get("subscription_run_id") or "") == run_id:
                        # Prefer final over provisional; otherwise replace in place.
                        if (not bool((existing or {}).get("_final"))) or bool(final):
                            rows[idx] = item
                        return
            # Without run_id, still dedupe by sid within the same batch for final rows.
            if final and item.get("sid"):
                for idx, existing in enumerate(rows):
                    if (
                        bool((existing or {}).get("_final"))
                        and int((existing or {}).get("sid") or 0) == int(item.get("sid") or 0)
                        and not str((existing or {}).get("subscription_run_id") or "").strip()
                    ):
                        rows[idx] = item
                        return
            rows.append(item)

    def _queue_failure_notice_v208(self, subscribe: Any, message: str, *, level: str = "retryable") -> bool:
        """返回 True 表示已进入批次缓冲，调用方不要再即时推送。

        注意：这里只缓冲失败文案，不计入最终 batch checked —— 最终计数由
        `_trace_transfer_result_v209` → `_record_transfer_diag_v209(final=True)` upsert。
        """
        text = str(message or "")
        hard = level == "error" or any(
            token in text for token in ("认证", "登录", "Authorization", "token 无效", "全局不可用", "API 不可用")
        )
        if hard:
            return False
        # Prefer structured diag carried on the current run when available.
        diag = None
        current = getattr(self, "_current_subscription_candidate_diags_v209", None)
        if isinstance(current, list) and current:
            try:
                from .transfer_diag_v209 import aggregate_subscription_diag
                diag = aggregate_subscription_diag(current)
                agg_state = str((diag or {}).get("final_state") or (diag or {}).get("state") or "")
                # Candidate soft-fail while SUCCESS/PENDING/SKIPPED remains: never escalate.
                if agg_state in {"SUCCESS", "PENDING"} or str(agg_state).startswith("SKIPPED"):
                    return True
                if agg_state and not str(agg_state).startswith("FAILED"):
                    return True
            except Exception:
                diag = None
        if not diag:
            diag = classify_transfer_message_v209({"message": text}, subscribe)
        code = str(diag.get("reason_code") or "")
        # Soft codes: do not create per-item failure rows; final upsert handles counting.
        if code in {
            "NO_LOCAL_RESOURCE", "NO_SUBSCRIPTION_MATCH", "CHANNEL_NO_ACTIONABLE_URL",
            "RESOURCE_CONTAINS_ONLY_EXISTING_EPISODES", "CURRENT_TARGET_ALREADY_SATISFIED",
            "NO_NEW_ACTION", "REMOTE_TASK_PENDING", "TRANSFER_ALREADY_RESERVED",
            "SUPERSEDED_BY_HIGHER_PRIORITY_SOURCE", "FUTURE_EPISODE_NOT_DUE",
            "SUBSCRIPTION_COMPLETED", "LIBRARY_ALREADY_SATISFIED",
            "PARTIAL_TRANSFER_PENDING", "COMPLETION_SYNC_PENDING",
            "TMDB_MATCH", "OFFICIAL_ALIAS_MATCH", "TITLE_MATCH",
        }:
            return True
        # Candidate identity rejects: suppress immediate unless this is already the aggregated FAILED final.
        if code in {"MEDIA_IDENTITY_UNCONFIRMED", "TMDB_ID_MISMATCH", "SELECTED_VIDEO_MISSING", "REMOTE_VIDEO_MISSING"}:
            agg_state = str((diag or {}).get("final_state") or (diag or {}).get("state") or "")
            if not agg_state.startswith("FAILED"):
                return True
            if isinstance(current, list) and len(current) > 1:
                # Multi-candidate run: only final FAILED aggregation may notify once later.
                if int(getattr(self, "_failure_batch_active_v208", 0) or 0) > 0:
                    return True
        lock = getattr(self, "_failure_batch_lock_v208", None) or threading.RLock()
        self._failure_batch_lock_v208 = lock
        with lock:
            if int(getattr(self, "_failure_batch_active_v208", 0) or 0) <= 0:
                return False
            rows = getattr(self, "_failure_batch_v208", None)
            if not isinstance(rows, list):
                rows = []
                self._failure_batch_v208 = rows
            rows.append({
                "sid": int(getattr(subscribe, "id", 0) or 0),
                "name": str(getattr(subscribe, "name", "") or ""),
                "message": text[:240],
                "diag": diag,
            })
            # Do NOT call _record_transfer_diag here — avoids double-count with final trace.
            return True

    def _flush_failure_batch_v208(self) -> None:
        lock = getattr(self, "_failure_batch_lock_v208", None) or threading.RLock()
        self._failure_batch_lock_v208 = lock
        with lock:
            active = int(getattr(self, "_failure_batch_active_v208", 0) or 0)
            if active > 0:
                self._failure_batch_active_v208 = active - 1
            if int(getattr(self, "_failure_batch_active_v208", 0) or 0) > 0:
                return
            legacy_rows = list(getattr(self, "_failure_batch_v208", None) or [])
            diag_rows = [
                row for row in (getattr(self, "_diag_batch_v209", None) or [])
                if bool((row or {}).get("_final", True))
            ]
            self._failure_batch_v208 = []
            self._diag_batch_v209 = []
        if not bool(getattr(self, "_notify", False)):
            return
        # Prefer structured diags; fall back to legacy failure rows.
        diags = list(diag_rows)
        if not diags and legacy_rows:
            for row in legacy_rows:
                sub = type("S", (), {"id": row.get("sid"), "name": row.get("name")})()
                diags.append(classify_transfer_message_v209({"message": row.get("message")}, sub))
        if not diags:
            return
        buckets = batch_summary_buckets(diags)
        highlights = []
        for diag in diags:
            code = str(diag.get("reason_code") or "")
            if code in {
                "TMDB_ID_MISMATCH", "SEASON_MISMATCH", "SHARE_EXPIRED",
                "CLOUD_TASK_SUBMIT_FAILED", "REMOTE_VERIFY_FAILED", "TRANSFER_FAILED",
                "MEDIA_IDENTITY_UNCONFIRMED",
            }:
                evidence = diag.get("evidence") or {}
                extra = ""
                if code == "SEASON_MISMATCH":
                    extra = f" 期望 S{evidence.get('expected_season')} 实际 {evidence.get('actual_seasons')}"
                elif code == "TMDB_ID_MISMATCH":
                    extra = f" 期望 {evidence.get('expected_tmdb')} 实际 {evidence.get('actual_tmdb')}"
                highlights.append(
                    f"#{diag.get('sid') or evidence.get('subscribe_id') or '-'} "
                    f"{diag.get('subscribe_title') or evidence.get('subscribe_title') or '-'} "
                    f"{code}{extra}"
                )
            if len(highlights) >= 8:
                break
        # Skip empty-noise-only batches (all NO_LOCAL) unless there are highlights/failures.
        if (
            buckets.get("failed", 0) <= 0
            and buckets.get("identity_reject", 0) <= 0
            and buckets.get("season_conflict", 0) <= 0
            and buckets.get("expired", 0) <= 0
            and buckets.get("success", 0) <= 0
            and buckets.get("pending", 0) <= 0
            and buckets.get("completed", 0) <= 0
            and not highlights
        ):
            # Still log; do not notify every NO_LOCAL-only round.
            self._plugin_log("INFO", "【转存诊断】批次仅本地暂无资源 checked=%s，跳过通知", buckets.get("checked", 0))
            return
        text = format_batch_summary(buckets, highlights)
        # Hard guard: never emit the old misleading counter wording / titles.
        banned_snippets = ("失败/待补搜", "光鸭转存检查完成", "本轮处理：")
        if any(token in text for token in banned_snippets):
            self._plugin_log("WARNING", "【通知护栏】结构化汇总含旧格式片段，已拦截发送")
            return
        if "失败/待补搜" in text:
            text = text.replace("失败/待补搜", "真正失败")
        try:
            try:
                from app.schemas.types import NotificationType
                mtype = NotificationType.Plugin
            except Exception:
                mtype = "Plugin"
            title = "⚠️ 光鸭转存检查汇总"
            if title == "⚠️ 光鸭转存检查完成" or "检查完成" in title:
                self._plugin_log("WARNING", "【通知护栏】拦截旧批次标题")
                return
            self.post_message(mtype=mtype, title=title, text=text[:1800])
        except Exception as err:
            self._plugin_log("WARNING", "【光鸭转存助手】【通知】批次汇总发送失败：%s", err)

    def _run_v1115_mode_batch(self, batch: List[int], trigger: str, mode: str, force: bool = False) -> None:
        self._begin_failure_batch_v208()
        try:
            return super()._run_v1115_mode_batch(batch, trigger, mode, force=force)
        finally:
            self._flush_failure_batch_v208()


__all__ = ["GuangYaProductionSafetyV208Mixin"]

